  id: string;
  title: string;
  body: string;
  createdAt: string;
};

let posts: Post[] = [
  {
    id: 'welcome',
    title: 'Welcome to Posts',
    body: 'Create a new post to see cache invalidation in action.',
    createdAt: new Date().toISOString(),
  },
];

const getPosts = unstable_cache(
  async () => posts,
  ['posts-list'],
  {
    tags: ['posts'],
  }
);

